// xxhash64: xxHash64 (seed 0) of 8 MiB of generated bytes: four lanes,
// each fed every fourth 64-bit word, then merged and mixed. One sequential
// pass over 32-byte stripes.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define P1 0x9E3779B185EBCA87ull
#define P2 0xC2B2AE3D27D4EB4Full
#define P3 0x165667B19E3779F9ull
#define P4 0x85EBCA77C2B2AE63ull

static uint64_t rotl(uint64_t x, int r) { return x << r | x >> (64 - r); }
static uint64_t round64(uint64_t acc, uint64_t lane) { return rotl(acc + lane * P2, 31) * P1; }
static uint64_t merge(uint64_t h, uint64_t v) { return (h ^ round64(0, v)) * P1 + P4; }
static uint64_t word(const uint8_t *p) {
    uint64_t w = 0;
    for (int i = 0; i < 8; i++) w |= (uint64_t)p[i] << (8 * i);
    return w;
}

int main(void) {
    int64_t n = 1 << 23;
    uint8_t *data = malloc(n);
    for (int64_t i = 0; i < n; i++) data[i] = (uint8_t)((i * 2654435761) >> 13 & 255);
    uint64_t v1 = P1 + P2, v2 = P2, v3 = 0, v4 = -P1;
    for (int64_t p = 0; p < n; p += 32) {
        v1 = round64(v1, word(data + p));
        v2 = round64(v2, word(data + p + 8));
        v3 = round64(v3, word(data + p + 16));
        v4 = round64(v4, word(data + p + 24));
    }
    uint64_t h = rotl(v1, 1) + rotl(v2, 7) + rotl(v3, 12) + rotl(v4, 18);
    h = merge(merge(merge(merge(h, v1), v2), v3), v4) + (uint64_t)n;
    h = (h ^ h >> 33) * P2;
    h = (h ^ h >> 29) * P3;
    h ^= h >> 32;
    printf("%016llx\n", (unsigned long long)h);
    free(data);
    return 0;
}
